namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}
namespace Atm;

public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
{
    public const int DailyLimit = 200;
    public const int FeeThreshold = 100;
    public const int WithdrawalFee = 5;
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));

    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    {
        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
        Operation.Deposit deposit => Deposit(account, deposit.Notes),
        _ => throw new ArgumentException("Opération inconnue.", nameof(operation)),
    };

    private AtmResult Withdraw(AccountState account, int amount)
    {
        if (amount <= 0 || amount % 10 != 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (account.WithdrawnToday + amount > DailyLimit)
        {
            return Refuse(AtmStatus.DailyLimitExceeded, account);
        }

        var fee = FeeFor(amount);
        if (amount + fee > account.Balance)
        {
            return Refuse(AtmStatus.InsufficientFunds, account);
        }

        if (FewestNotes(amount, Available()) is not { } combination)
        {
            return Refuse(AtmStatus.CannotDispense, account);
        }

        var dispensed = NoteCounts.None;
        foreach (var pass in Passes(combination))
        {
            if (!_dispenser.Dispense(pass))
            {
                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
            }

            dispensed += pass;
        }

        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);

        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    }

    private AtmResult Deposit(AccountState account, NoteCounts notes)
    {
        if (notes.Total <= 0)
        {
            return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
        {
            return Refuse(AtmStatus.CassetteJammed, account);
        }

        var after = _dispenser.Stock + notes;
        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
        {
            return Refuse(AtmStatus.CassetteFull, account);
        }

        if (!_dispenser.Load(notes))
        {
            return Refuse(AtmStatus.DispenserFault, account);
        }

        return new AtmResult(
            AtmStatus.Ok,
            NoteCounts.None,
            0,
            account with { Balance = account.Balance + notes.Value });
    }

    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
        new(status, NoteCounts.None, 0, account);

    private static int FeeFor(int amount) => amount > FeeThreshold ? WithdrawalFee : 0;

    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    private NoteCounts Available()
    {
        var stock = _dispenser.Stock;

        return _dispenser.Jammed switch
        {
            Denomination.Fifty => stock with { Fifties = 0 },
            Denomination.Twenty => stock with { Twenties = 0 },
            Denomination.Ten => stock with { Tens = 0 },
            _ => stock,
        };
    }

    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
    {
        NoteCounts? best = null;
        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
        {
            var afterFifties = amount - fifties * 50;
            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
            {
                var rest = afterFifties - twenties * 20;
                if (rest % 10 != 0 || rest / 10 > available.Tens)
                {
                    continue;
                }

                var candidate = new NoteCounts(fifties, twenties, rest / 10);
                if (best is not { } current || candidate.Total < current.Total)
                {
                    best = candidate;
                }
            }
        }

        return best;
    }

    /// <summary>Découpe la combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
    {
        var remaining = notes;
        while (remaining.Total > 0)
        {
            var room = MaxNotesPerPass;
            var fifties = Math.Min(remaining.Fifties, room);
            room -= fifties;
            var twenties = Math.Min(remaining.Twenties, room);
            room -= twenties;
            var tens = Math.Min(remaining.Tens, room);

            var pass = new NoteCounts(fifties, twenties, tens);
            remaining -= pass;

            yield return pass;
        }
    }
}
