    [Theory]
    [InlineData(Denomination.Fifty)]
    [InlineData(Denomination.Twenty)]
    [InlineData(Denomination.Ten)]
    public void Deposit_FullCassetteOfEachDenomination_IsCassetteFull(Denomination denomination)
    {
