            _ => N(0, 0, 5),
        };
        var dispenser = new RecordingDispenser(new MoneyDispenser(stock));
        var result = new CashMachine(dispenser).Execute(new AccountState(0, 0), new Operation.Deposit(N(1, 1, 1)));

